/* Generated by scripts/prepare-pwa.mjs. The cache version tracks all shipped files. */
'use strict';
const CACHE_PREFIX = 'tabi-offline-';
const CACHE_NAME = '__CACHE_NAME__';
const PRECACHE = __PRECACHE__;
const ASSET_PATHS = new Set(PRECACHE);
const ASSET_HASHES = __ASSET_HASHES__;
const APP_URL = new URL('./', self.location.href);

self.addEventListener('install', event => {
  // A partial download must never become the active offline version.
  event.waitUntil(caches.open(CACHE_NAME).then(cache =>
    cache.addAll(PRECACHE.map(path => new Request(new URL(path, APP_URL), {cache: 'reload'})))
  ));
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter(name => name.startsWith(CACHE_PREFIX) && name !== CACHE_NAME).map(name => caches.delete(name)));
    await self.clients.claim();
  })());
});

async function resolveAppRequest(request, cacheOnly = false) {
  const url = new URL(request.url);
  const path = url.pathname;
  const cache = await caches.open(CACHE_NAME);
  // Always use one complete release, so an update cannot mix old JS with new content.
  const cached = await cache.match(request.mode === 'navigate' ? APP_URL.href : new URL(path, APP_URL).href);
  if (cached) return cached;
  if (cacheOnly) return new Response('Offline file unavailable. Reconnect and retry the offline download.', {status: 503});
  try { return await fetch(request); }
  catch {
    return new Response('Tabi is not saved for offline use yet. Connect once, open Tabi, and wait for Ready offline.', {
      status: 503, headers: {'Content-Type': 'text/plain; charset=utf-8'}
    });
  }
}

self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== APP_URL.origin) return;
  // Leave external links, API calls and unrelated resources outside the app cache.
  if (request.mode === 'navigate' && url.pathname !== '/' && url.pathname !== '/index.html') return;
  if (request.mode === 'navigate' || ASSET_PATHS.has(url.pathname)) {
    event.respondWith(resolveAppRequest(request));
  }
});

self.addEventListener('message', event => {
  if (event.data?.type === 'SKIP_WAITING') {
    event.waitUntil(self.skipWaiting());
    return;
  }
  if (!['OFFLINE_STATUS', 'VERIFY_OFFLINE', 'REPAIR_OFFLINE'].includes(event.data?.type) || !event.ports?.[0]) return;
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE_NAME);
    let mismatch = false;
    if (event.data.type === 'REPAIR_OFFLINE') {
      for (const path of PRECACHE) {
        const url = new URL(path, APP_URL);
        if (await cache.match(url.href)) continue;
        try {
          const response = await fetch(new Request(url, {cache: 'reload'}));
          if (!response.ok) continue;
          const digest = Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', await response.clone().arrayBuffer()))).map(n => n.toString(16).padStart(2,'0')).join('');
          // Never fill an older cache with a different release's files.
          if (digest !== ASSET_HASHES[path]) {mismatch = true;continue;}
          await cache.put(url.href, response);
        } catch { /* Keep the existing release usable and report any missing files. */ }
      }
    }
    const missing = [];
    for (const path of PRECACHE) {
      const response = await resolveAppRequest(new Request(new URL(path, APP_URL)), true);
      if (!response.ok) missing.push(path);
    }
    event.ports[0].postMessage({ready: missing.length === 0, files: PRECACHE.length, missing, mismatch, version: CACHE_NAME});
  })().catch(() => event.ports[0].postMessage({ready: false, files: 0, missing: ['offline-storage']})));
});
